n=17
center=8
g=[[0]*n for _ in range(n)]
for r in range(n):
    lo=max(0,center-r)
    hi=min(n-1,center+r)
    if r<=center:
        g[r][lo]=2; g[r][hi]=2
    for c in range(lo,hi+1):
        if (c-r-center)%4==0 and g[r][c]!=2:
            g[r][c]=1
for row in g: print(' '.join(map(str,row)))
